create or replace TABLE KFL_PRODUCTION.DBP_DATA.LAGERBEW_DET_DELTA_2 (
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Der Mandant_2 1 steht im DWH für Deutschland (der Wert 222 aus dem SAP System für Deutschland wird in Wert 1 umgewandelt).',
	LAGERBEW_BELEG_ID NUMBER(18,0) NOT NULL COMMENT 'Das Feld enthält die ID der Lagerbewegung und dient zusammen mit dem Kalenderjahr der eindeutigen Identifikation der Lagerbewegung aus mblnr.',
	LAGERBEW_BELEG_POS_ID NUMBER(38,0) NOT NULL COMMENT 'Das Feld enthält die Nummer einer Lagerbelegbewegungsposition und dient zusammen mit der Lagerbewegungs ID und dem Kalenderjahr der eindeutigen Identifikation der Lagerbewegungsposition. Aus zeile.',
	KJ NUMBER(38,0) NOT NULL COMMENT 'Dieses Attribut enthält das entsprechende Kalenderjahr und wird benötgit um einen Beleg in Kombination mit der Belegnummer eindeutig zu identifizieren. Aus mjahr.',
	LAGER_BEWART_ID VARCHAR(3) NOT NULL COLLATE 'en-ci' COMMENT 'Dieses Feld enthält die Bewegungsart einer Lagerbewegung, aus bwart. Lookup-Tabelle ist l_lager_bewart.',
	ART_ID NUMBER(38,0) COMMENT 'Input: Artikel_2 - Id einschließlich der Generationen-ID (9-stellig); Output: 7stellige L&S-ID + Counter = 8stellige Artikel_2-ID. WWNNNNPC (Warengruppe, Nummer, Prüfziffer, Counter) Regel: Neuer Artikel_2 -> Counter +1.',
	GRUND_ID VARCHAR(10) NOT NULL COLLATE 'en-ci' COMMENT 'Dieses Feld enthält den Grund für eine_2 Lagerbewegung.',
	WUP_ID NUMBER(38,0) COMMENT 'WarenUmschlagsPlatz aus mseg.werks.',
	NB_ID NUMBER(38,0) NOT NULL COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer.',
	AUTO_FG VARCHAR(1) NOT NULL COLLATE 'en-ci' COMMENT 'Attribut auto_fg kennzeichnet Belegpositionen, die automatisch generiert wurden. Aus xauto. Wertevorrat: S, X, L, blank. Es handelt sich also nicht um ein Flag, wie die Bezeichnung suggeriert!) ',
	LAGERORT_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'Schlüssel für die Lagerorte. Die Lagerorte sind pro Werk / Betrieb eindeutig. Aus lgort.',
	GP_ID NUMBER(38,0) NOT NULL COMMENT 'Geschäftspartner-ID (Lieferanten-ID), aus lifnr.',
	EINKAUFSORGANISATION_ID NUMBER(38,0) COMMENT 'Die Einkaufsorganisation_id ist erforderlich um einen Lieferanten der Tabelle GP_2 zusammen mit dem Attribut gp_id eindeutig zu identifizieren. 1000 = Warenlieferant, 5000 = Frischelieferant, 9000 = ? (könnte es auch geben).',
	SOLL_HABEN_KZ VARCHAR(1) NOT NULL COLLATE 'en-ci' COMMENT 'Zeigt, auf welcher Seite des Kontos (S = Soll, H = Haben) die Fortschreibung der Verkehrszahlen erfolgt. Aus shkzg.',
	WRG_ID VARCHAR(3) NOT NULL COLLATE 'en-ci' COMMENT 'Kurzbezeichnung der Währung, z.Bsp. CZK, EUR.',
	BEST_BELEG_ID NUMBER(18,0) COMMENT 'Das Feld enthält die Beleg-ID der Bestellung und dient der eindeutigen Identifikation des Bestellbelegs. Aus ebeln.',
	BEST_BELEG_POS_ID NUMBER(38,0) NOT NULL COMMENT 'Das Feld enthält die Nummer einer Bestellposition und dient zusammen mit der Bestell-ID der eindeutigen Identifikation der Bestellbelegposition. Aus ebelp.',
	BETRAG_LAGERBEW NUMBER(18,4) WITH MASKING POLICY #unknown_policy COMMENT 'Betrag der Belegposition in der Hauswährung des Buchungskreises. Aus dmbtr. Entspricht dem eknetto_bnk.',
	BETRAG_VERKAUF NUMBER(18,2) NOT NULL COMMENT 'Listenpreis (Verkaufspreis brutto * Menge). Das Feld entspricht mseg.vkwrt.',
	ERFSNGS_MENGE_EINH_ID VARCHAR(3) NOT NULL COMMENT 'Dieses Feld enthält die ID der Mengeneinheit für die Umrechnung der Basismenge in die alternative Mengeneinheit. Dazu ist der Umrechnungsfaktor aus der DWH Tabelle art_umrechnung_faktor_per_2 pro Material zu ermitteln. Aus erfme.',
	LAGERPLATZ_ID VARCHAR(10) COLLATE 'en-ci' COMMENT 'ID des Lagerplatzes. Vierte Ebene der Lagerhierarchie. Aus lgpla.',
	KUNDE_ID VARCHAR(10) COLLATE 'en-ci' COMMENT 'ID des Kunden. Aus kunnr.',
	MENGE_LAGERBEW_KOLLI NUMBER(18,3) NOT NULL COMMENT 'Dieses Feld enthält die Menge in der Kollimengeneinheit. Der gültige Umrechnungsfaktor wird aus der DWH Tabelle art_umrechnung_faktor_per_2 ermittelt.',
	MENGE_LAGERBEW_BME NUMBER(18,3) NOT NULL COMMENT 'Mengenanteil der Gesamtbestellmenge, dem diese Kontierungsposition zugeordnet wird. Die eingegebene Menge bestimmt, welcher Anteil der Kosten auf diese Kontierungsposition verteilt wird. Aus menge.',
	MENGE_LAGERBEW_PALETTE NUMBER(18,3) COMMENT 'Dieses Feld enthält die Menge in der Palettenmengeneinheit. Der erforderliche Umrechnungsfaktor wird aus den DWH Tabellen art_vorschlagswert_per_2 und art_umrechnung_faktor_per_2 ermittelt.',
	MENGE_LIEFERSCHEIN NUMBER(18,3) NOT NULL COMMENT 'Menge in Mengeneinheit aus Lieferschein, aus lsmng. Gibt die Menge an, die vom Lieferanten als gelieferte Menge auf Begleitpapieren (z.B. Lieferschein) ausgewiesen wird.',
	MENGE_LIEF NUMBER(18,3) NOT NULL COMMENT 'Gibt die gelieferte Menge in Bestellpreismengeneinheit an. Aus bpnmg.',
	MENGE_ERF NUMBER(18,3) NOT NULL COMMENT 'Dieses Feld enthält die Menge in der Erfassungsmengeneinheit. Der erforderliche Umrechnungsfaktor wird aus den DWH Tabellen art_vorschlagswert_per_2 und art_umrechnung_faktor_per_2 ermittelt. Aus erfmg.',
	EMPFAENGER_ID NUMBER(38,0) COMMENT 'Dieses Feld enthält das empfangende Werk für diese Lagerbewegung, aus umwrk. Dieses Feld enthält die Fachschlüssel der VZ.',
	DAT_BUCH DATE NOT NULL COMMENT 'Datum, unter dem der Beleg in der Buchhaltung bzw. in der Kostenrechnung_2 erfasst wird. Das Feld wird aus der Kopftabelle \"vererbt\", um einen PPI darüber bilden zu können (Performance!).',
	LAGERBEW_BELEG_STORNO_ID NUMBER(18,0) COMMENT 'Beleg-ID des stornierten Beleges. Referenz von Storno zu storniertem Beleg in der Tabelle lagerbew_det. Aus smbln.',
	LAGERBEW_BELEG_POS_STORNO_ID NUMBER(38,0) COMMENT 'Belegposition des stornierten Beleges. Referenz von Storno zu storniertem Beleg in der Tabelle lagerbew_det. Aus smblp.',
	LAGERBEW_BELEG_STORNO_KJ NUMBER(38,0) COMMENT 'Belegposition des stornierten Beleges. Referenz von Storno zu storniertem Beleg in der Tabelle lagerbew_det. Aus sjahr.',
	BETRAG_VK_NETTO NUMBER(18,2) NOT NULL COMMENT 'Entspricht dem Attribut vkwra aus der Tabelle mseg.',
	BETRAG_BELEGFLUSS_WG_ART NUMBER(18,2) DEFAULT 0 COMMENT 'Betrag aus der Tabelle best_belegfluss. Denormalisierung zur Performancesteigerung bei WBF Abfragen. Nur gefüllt bei WG Erfassartikeln, sonst Null. Nicht im logischen Modell.',
	MANDANT_ID_KUNDE NUMBER(38,0) COMMENT 'Der Mandant_2 des Kunden, kann ein anderer sein als der des WUP.',
	MANDANT_ID_EMPFAENGER NUMBER(38,0) COMMENT 'Der Mandant_2 des Empfängers, kann ein anderer sein als der des WUP.',
	BW_VORGANG_ID NUMBER(38,0) COMMENT 'Dieses Feld wird im SAP-BW gebildet, u.a aus der Lager Bewegungsart und dem Soll-Haben-Kennzeichen.',
	BETRAG_VERKAUF_IST NUMBER(18,2) NOT NULL DEFAULT 0 COMMENT 'Tatsächlicher Marktpreis (Verkaufspreis brutto * Menge). Das Feld entspricht mseg.exvkw.',
	BETRAG_VK_NETTO_VZ NUMBER(18,4) NOT NULL DEFAULT 0 COMMENT 'Nettobetrag. Kein Original-mseg-Feld. Wird im DWH nur für Verteilzentren angereichert.',
	BETRAG_VERKAUF_IST_NETTO NUMBER(18,4) NOT NULL DEFAULT 0 COMMENT 'Tatsächlicher Marktpreis netto ((Verkaufspreis brutto minus MWSt) * Menge). Das Feld wird im DWH aus mseg.exvkw und Mehrwertsteuerbetrag errechnet.',
	BETRAG_EINSTANDSPREIS NUMBER(18,4) WITH MASKING POLICY #unknown_policy COMMENT 'Betrag der Belegposition bewertet zum Einstandspreis. Wird nur für KMO-Daten angereichert.',
	GP_ID_ZL NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Lieferantennummer. In der Versorgung wird der Lieferant aus der Bezugsquellenfindung angereichert - nur für KMO. Bei ZL-Bewegungsarten ist die gp_id in dieser Tabelle leer.',
	BQ_FINDUNG_ID NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'ID zur Kennzeichnung des Ausstiegspunkts aus dem Kreisprozess. Wird bei der Versorgung angereichert. Nur für KMO gefüllt, sonst 0',
	MENGE_BESTAND_BME NUMBER(18,3) NOT NULL DEFAULT 0 COMMENT 'Gesamter bewerteter Bestand vor der Buchung in Basismengeneinheiten. Aus lbkum.',
	WERT_BESTAND NUMBER(18,4) NOT NULL DEFAULT 0 COMMENT 'Wert des gesamten bewerteten Bestands vor der Buchung. Aus salk3.',
	SYSTEM_ID NUMBER(38,0) COMMENT 'Spezifiziert das Quellsystem, aus dem die Daten kommen.',
	BUCHUNGSKREIS_ID NUMBER(38,0) COMMENT 'Zuordnung des Buchungskreises zu dem WUP_2 über die SAP Quelle T001K und T001. Der Buchungskreis entspricht unter dem Mandanten einer Zusammenfassung von Werken (Hierarchie: Mandant_2, Buchungskreis, Werk / Betrieb). Bsp: Buchungskreis 282 entspricht Kaufland.',
	SHKUM VARCHAR(1) NOT NULL COLLATE 'en-ci' DEFAULT ' ' COMMENT 'Soll / Haben Kennzeichen der Umbewertung_2, aus der Quellspalte shkum.',
	KOSTENSTELLE_ID VARCHAR(10) NOT NULL COLLATE 'en-ci' DEFAULT '          ' COMMENT 'ID der Kostenstelle, z.Bsp. 9676-400, aus dem Quellfeld kostl. Hat eine_2 Referenz zur Tabelle kostenstelle_per.',
	SACHKONTO_ID VARCHAR(10) NOT NULL COLLATE 'en-ci' DEFAULT '          ' COMMENT 'Alphanumerischer Wert aus dem Quellfeld sakto. Hat KEINE Referenz zur DWH-Tabelle l_sachkonto!',
	ART_ID_EMPFAENGER NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Empfangendes / abgebendes Material aus ummat. Referenz zur Tabelle art.',
	LAGERORT_ID_EMPFAENGER VARCHAR(4) NOT NULL COLLATE 'en-ci' DEFAULT '    ' COMMENT 'Empfangender / Abgebender Lagerort, aus umlgo. Referenz zu l_lagerort.',
	ART_ID_BF NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Artikel_2, auf dem der Bestand geführt wird, aus matbf. Referenz zu art.',
	LAGERBEW_BELEG_POS_MUTTER_ID NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Verweis auf die umsortierte Lagerbewegungsbelegposition des zu diesem Artikel_2 übergeordneten Artikels (falls er existiert). Aus parent_id.\n            Displays (a.k.a. Aussteller) als auch die Komponenten / Artikel_2 in einem Display werden im Lagerbewegungsbeleg als eigene Positionen / Artikel_2 aufgeführt. Um Komponenten und Displays einander zuzuordnen, wurden in SAP neue Spalten hinzugefügt, welche die Belegzeilen (lagerbew_beleg_pos_id) neu sortieren und dann die neue Displaybelegzeile (line_id) bei den Komponenten angibt (aktuelle Spalte). In der veränderten Sortierung (line_id) werden die Komponenten ans Ende des Belegs gestellt: erst kommen alle Artikel_2 ohne Kopfartikel (lagerbew_beleg_pos_mutter_id = 0) und danach die Komponenten. In lagerbew_beleg_pos_mutter_id (aktuelle Spalte) steht dann der Wert der umsortierten Displaybelegzeile aus line_id.\n            (Der Spaltenname wurde zur Konsistenz an bestehende Spalten in anderen lagerbew_2 Tabellen angepasst. Ein besserer Name wäre_2 gewesen: lagerbew_beleg_parent_pos_sort_id oder lagerbew_beleg_pos_sort_mutter_id.)',
	LINE_ID NUMBER(38,0) NOT NULL COMMENT 'Umsortierte Lagerbewegungsbelegpositionen zur Verbindung von Displays und Displaykomponenten (entspricht der Form früherer Belege vor der Einführung der Display / Komponenten Beziehung). Aus line_id.\n            Displays (a.k.a. Aussteller) als auch die Komponenten / Artikel_2 in einem Display werden im Lagerbewegungsbeleg als eigene Positionen / Artikel_2 aufgeführt. Um Komponenten und Displays einander zuzuordnen, wurden in SAP neue Spalten hinzugefügt, welche die Belegzeilen (lagerbew_beleg_pos_id) neu sortieren und dann die neue Displaybelegzeile (line_id) bei den Komponenten angibt (lagerbew_beleg_pos_mutter_id). In der veränderten Sortierung (aktuellen Spalte) werden die Komponenten ans Ende des Belegs gestellt: erst kommen alle Artikel_2 ohne Kopfartikel (lagerbew_beleg_pos_mutter_id = 0) und danach die Komponenten. In lagerbew_beleg_pos_mutter_id steht dann der Wert der umsortierten Displaybelegzeile aus line_id (aktuelle Spalte).\n            (Der Spaltenname wurde zur Konsistenz an bestehende Spalten in anderen lagerbew_2 Tabellen angepasst. Ein besserer Name wäre_2 gewesen: lagerbew_beleg_pos_sort_id.)',
	ENDLIEF_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag zeigt an, ob eine_2 Lieferung abgeschlossen ist. Hergeleitet aus dem Endlieferungskennzeichen elikz.',
	XRUEM_FG NUMBER(38,0) NOT NULL COMMENT 'Flag: Rückbuchung in die Vorperiode erlaubt. Abgeleitet aus xruem.',
	BETRAG_EXBWR NUMBER(18,4) NOT NULL DEFAULT 0 WITH MASKING POLICY #unknown_policy COMMENT 'Extern eingegebener Buchungsbetrag in Hauswährung. Aus exbwr.',
	BETRAG_BNK NUMBER(18,4) NOT NULL DEFAULT 0 COMMENT 'Bezugsnebenkosten in Hauswährung. Aus bnbtr.',
	BETRAG_UMBEWERTUNG NUMBER(18,4) NOT NULL DEFAULT 0 WITH MASKING POLICY #unknown_policy COMMENT 'Betrag der Umbewertung_2 beim Rückbuchen in die Vorperiode. Aus dmbum.',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	DISPLAY_ART_ID NUMBER(38,0) DEFAULT -1 COMMENT 'Artikel_2-ID des Displays im Lagerbewegungsbeleg. Displays (a.k.a. Aussteller) als auch die Komponenten / Artikel_2 in einem Display werden im Lagerbewegungsbeleg als eigene Positionen / Artikel_2 aufgeführt. Über diese Spalte bekommen die Komponenten die art_id des zugehörigen Displays. Wird bei der Beladung gefüllt.',
	constraint PK_LAGERBEW_DET_DELTA primary key (MANDANT_ID, LAGERBEW_BELEG_ID, LAGERBEW_BELEG_POS_ID, KJ)
)COMMENT='WWC - Hier sind aktuelle Daten geladen, die nach der eigentlichen täglichen Beladung noch eingetroffen sind. Quelle ist mseg'
;